mapper.delete:
DELETE FROM question_posts
WHERE id = #{postId}
  AND user_id = #{userId}

mapper.update:
UPDATE question_posts
SET checked_commentid = #{checkedCommentid},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{postId}
  AND EXISTS (
      SELECT 1
      FROM community_comments
      WHERE id = #{checkedCommentid}
        AND question_post_id = #{postId}
  )
